use qcore::{
    account_address, chain_id_from_name, sign_call, sign_payable_call, vm_call_fee, LOCAL_CHAIN_ID,
    SEED_LEN,
};
use qtv_tx::{sign, Body, Call, TESTNET_CHAIN_ID};

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn shared_seed() -> [u8; SEED_LEN] {
    let mut seed = [0u8; SEED_LEN];
    for (i, byte) in seed.iter_mut().enumerate() {
        *byte = i as u8;
    }
    seed
}

#[test]
fn the_derived_addresses_match_the_qcore_js_vector() {
    let seed = shared_seed();
    assert_eq!(
        account_address(&seed, 7),
        "Q133C9CYVYZNQ7X25H0JJWUDHU8U5G3DN7CQC4J64LFTRSUH66ZNCQWDRA8R"
    );
    assert_eq!(
        account_address(&seed, 8),
        "Q1H2PLGDKK73HPS8PM4EQT5NL7MV8K9ENUMCDQC4V0GKDEJC3FTYAS70UVL8"
    );
}

#[test]
fn the_transfer_body_reproduces_the_qcore_js_vector() {
    let seed = shared_seed();
    let sender = qtv_account::derive(&seed, 7);
    let target = account_address(&seed, 8);
    let body = Body::with_context(
        sender.address(),
        3,
        21_000,
        1_000_000,
        Call::new(target.clone(), vec![0xde, 0xad, 0xbe, 0xef]),
        0,
        LOCAL_CHAIN_ID,
    )
    .calling();
    let frozen = sign(&sender, &body);
    let body_bytes = "";
    assert_eq!(hex(&qtv_codec::to_bytes(&body)), body_bytes);
    assert!(
        hex(&qtv_codec::to_bytes(&frozen)).starts_with(body_bytes),
        "the signed body prefix is the frozen QCore.js transfer body"
    );
    assert_eq!(
        frozen.id(),
        "QTX1UCZULSSQ2DLT7YR4QHH4WM95J2S2GYDZQUU38TEMTMJQ6TQLPZ3QSXF8ZV"
    );
    let signed = sign_call(
        &seed,
        7,
        &target,
        vec![0xde, 0xad, 0xbe, 0xef],
        3,
        21_000,
        1_000_000,
        LOCAL_CHAIN_ID,
        BOUNDED_VALID_UNTIL,
        BOUNDED_TRANSFER_FEE,
    )
    .unwrap();
    let bounded = sign(&sender, &body.valid_until(BOUNDED_VALID_UNTIL));
    assert_eq!(signed.tx_bytes, qtv_codec::to_bytes(&bounded));
    assert_eq!(signed.tx_id, BOUNDED_TRANSFER_TX_ID);
    assert_eq!(hex(&signed.tx_bytes), BOUNDED_TRANSFER_TX_HEX);
}

const BOUNDED_VALID_UNTIL: u64 = 300;

const BOUNDED_TRANSFER_FEE: u128 = 500;

const BOUNDED_TRANSFER_TX_ID: &str =
    "QTX18EPDMFLYF6PNNYS77NER6ZGR2EVDKTPGPDSHR9UNRFLR5MEUP8LSJECFHW";

const BOUNDED_TRANSFER_TX_HEX: &str = "";

const BOUNDED_PAYABLE_TX_ID: &str =
    "QTX1PJSDDHCWVYWPK2J0LUH9DR9JEY7JGLNKVZNQGNHM3WJGRFM85RMQN9G5SH";

const BOUNDED_PAYABLE_TX_HEX: &str = "";

#[test]
fn the_bounded_payable_transaction_reproduces_the_qcore_js_vector() {
    let seed = shared_seed();
    let sender = qtv_account::derive(&seed, 7);
    let target = account_address(&seed, 8);
    let body = Body::with_context(
        sender.address(),
        3,
        21_000,
        1_000_000,
        Call::new(target.clone(), vec![0xde, 0xad, 0xbe, 0xef]),
        250_000,
        TESTNET_CHAIN_ID,
    )
    .calling()
    .valid_until(BOUNDED_VALID_UNTIL);
    let bounded = sign(&sender, &body);
    let signed = sign_payable_call(
        &seed,
        7,
        &target,
        vec![0xde, 0xad, 0xbe, 0xef],
        250_000,
        3,
        21_000,
        1_000_000,
        TESTNET_CHAIN_ID,
        BOUNDED_VALID_UNTIL,
        BOUNDED_TRANSFER_FEE,
    )
    .unwrap();
    assert_eq!(signed.tx_bytes, qtv_codec::to_bytes(&bounded));
    assert_eq!(signed.tx_id, BOUNDED_PAYABLE_TX_ID);
    assert_eq!(hex(&signed.tx_bytes), BOUNDED_PAYABLE_TX_HEX);
}

#[test]
fn the_payable_transaction_reproduces_the_qcore_js_vector() {
    let seed = shared_seed();
    let sender = qtv_account::derive(&seed, 7);
    let target = account_address(&seed, 8);
    let call = Call::new(target, vec![0xde, 0xad, 0xbe, 0xef]);
    let body = Body::with_context(
        sender.address(),
        3,
        21_000,
        1_000_000,
        call,
        250_000,
        TESTNET_CHAIN_ID,
    )
    .calling();
    let wrapper = sign(&sender, &body);
    assert!(qtv_tx::verify(&wrapper, sender.public_key()));
    assert_eq!(
        wrapper.id(),
        "QTX18MRMZTQ5EPD30MU9FAXLNT076JFV53K3C229TEFXUFS9VHSF3LZSZCN7H6"
    );
}

#[test]
fn the_target_case_never_moves_the_signed_bytes() {
    let seed = shared_seed();
    let upper = account_address(&seed, 8);
    let lower = upper.to_ascii_lowercase();
    assert_ne!(upper, lower);
    let signed_upper = sign_call(
        &seed,
        7,
        &upper,
        vec![1, 2],
        3,
        21_000,
        vm_call_fee(500, 21_000),
        LOCAL_CHAIN_ID,
        300,
        500,
    )
    .unwrap();
    let signed_lower = sign_call(
        &seed,
        7,
        &lower,
        vec![1, 2],
        3,
        21_000,
        vm_call_fee(500, 21_000),
        LOCAL_CHAIN_ID,
        300,
        500,
    )
    .unwrap();
    assert_eq!(signed_upper.tx_bytes, signed_lower.tx_bytes);
    assert_eq!(signed_upper.tx_id, signed_lower.tx_id);
}

#[test]
fn the_display_string_maps_to_the_signed_chain_id() {
    assert_eq!(chain_id_from_name(qcore::LOCAL_CHAIN_NAME), LOCAL_CHAIN_ID);
    assert_eq!(
        chain_id_from_name(qcore::TESTNET_CHAIN_NAME),
        qcore::testnet_chain_id()
    );
    assert_eq!(
        chain_id_from_name(qtv_tx::TESTNET_CHAIN_NAME),
        TESTNET_CHAIN_ID
    );
    assert_eq!(
        chain_id_from_name(qcore::MAINNET_CHAIN_NAME),
        qcore::MAINNET_CHAIN_ID
    );
    assert_eq!(
        chain_id_from_name("Q-test-net-1"),
        4_032_652_574_364_075_694
    );
}
